int receive_and_process_message(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int msg_flags) {
    int result = 0;

    if (!iocb || !sock || !msg) {
        return -EINVAL;
    }

    if (size == 0) {
        return 0;
    }

    if (size > SSIZE_MAX) {
        size = SSIZE_MAX;
    }

    result = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags);

    if (result < 0) {
        return result;
    }

    if (result > 0) {
        msg->msg_flags = msg_flags;
        msg->msg_len = result;
    }

    return result;
}
